func (q *Queries) SearchVehicles(ctx context.Context, arg SearchVehiclesParams) ([]SearchVehiclesRow, error) {
	rows, err := q.db.QueryContext(ctx, searchVehicles,
		arg.TenantID,
		arg.Search,
		arg.StatusAll,
		arg.Status,
		arg.FleetClassAll,
		arg.FleetClass,
		arg.OwnershipAll,
		arg.Ownership,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchVehiclesRow
	for rows.Next() {
		var i SearchVehiclesRow
		if err := rows.Scan(
			&i.ID,
			&i.RegistrationNumber,
			&i.VehicleNumber,
			&i.VehicleType,
			&i.Capacity,
			&i.FuelType,
			&i.InsuranceExpiry,
			&i.FitnessExpiry,
			&i.PermitExpiry,
			&i.Status,
			&i.CurrentMileage,
			&i.TenantID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.FleetClass,
			&i.Ownership,
			&i.FleetNumber,
			&i.Description,
			&i.Manufacturer,
			&i.ManufCountry,
			&i.Model,
			&i.ConstrYearMonth,
			&i.AcquisitionValue,
			&i.AcquisitionCurrency,
			&i.AcquisitionDate,
			&i.PurchaseVendor,
			&i.ValidFrom,
			&i.ValidTo,
			&i.FacilityID,
			&i.MaintPlant,
			&i.PlanningPlant,
			&i.CompanyCode,
			&i.BusinessArea,
			&i.CostCenter,
			&i.AssetNo,
			&i.FleetObjectNo,
			&i.ChassisNo,
			&i.VehicleCategory,
			&i.EngineNumber,
			&i.EnginePower,
			&i.EngineCapacity,
			&i.CylinderCount,
			&i.MaxSpeed,
			&i.Weight,
			&i.WeightUnit,
			&i.LoadVolume,
			&i.VolumeUnit,
			&i.SecondaryFuel,
			&i.UsageIndicator,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

